<?php declare(strict_types=1); require __DIR__ . '/admin.php'; requireAdmin($database); if ($_SERVER['REQUEST_METHOD'] === 'POST') { $statement = $database->prepare('INSERT INTO categories (name, slug, description) VALUES (:name, :slug, :description)'); $statement->execute(['name' => trim((string) $_POST['name']), 'slug' => trim((string) $_POST['slug']), 'description' => trim((string) $_POST['description'])]); } $categories = $database->query('SELECT id, name, slug, description FROM categories ORDER BY name')->fetchAll(); adminHeader('Manage categories'); ?><h1>Manage categories</h1><form method="post"><input name="name" placeholder="Name" required><input name="slug" placeholder="slug" required><input name="description" placeholder="Description"><button>Create category</button></form><ul><?php foreach ($categories as $category): ?><li><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?> (<?= htmlspecialchars($category['slug'], ENT_QUOTES, 'UTF-8') ?>)</li><?php endforeach; ?></ul><?php adminFooter(); ?>
